#!/usr/bin/env bash
#
# Regenerate `src/resources.rs`.
#

sanitize_identifier() {
  tr -cd 'a-z_' | tr '[:lower:]' '[:upper:]'
}

(
  echo $'
// THIS FILE HAS BEEN GENERATED BY generate_resources.sh
// DO NOT EDIT IT BUT INSTEAD CHANGE THE GENERATOR
'

  for modelpath in ./resources/*; do
    if ! [[ -d "$modelpath" ]]; then
      continue
    fi

    modelident="$(basename "${modelpath}" | sanitize_identifier)"
    declare -a up_files down_files
    up_files=("${modelpath}/up"*.wav)
    down_files=("${modelpath}/down"*.wav)

    echo $"
pub const ${modelident}_DOWN: [&[u8]; ${#down_files[@]}] = [
    $(for file in "${down_files[@]}"; do
      echo "include_bytes!(\".${file}\"),"
    done)
];

pub const ${modelident}_UP: [&[u8]; ${#up_files[@]}] = [
    $(for file in "${up_files[@]}"; do
      echo "include_bytes!(\".${file}\"),"
    done)
];
"
  done
) | rustfmt | tee src/resources.rs

echo "(Written to src/resources.rs)" >&2
